SELECT percentile_cont(0.9) within GROUP (ORDER BY instability_score) AS p90_instability_score, COUNT(DISTINCT CASE WHEN instability_score > p90_instability_score THEN subject_id END) AS patients_above_threshold, SUM(CASE WHEN deathtime IS NOT NULL THEN 1 ELSE 0 END) AS mortality_count, AVG(los) AS average_length_of_stay FROM instability JOIN ards ON instability.subject_id = ards.subject_id JOIN mortality ON ards.subject_id = mortality.subject_id WHERE instability_score IS NOT NULL GROUP BY p90_instability_score;